def sum_prefix_max_gcd_pairs(nums):
    from math import gcd
    values=[];maximum=0
    for value in nums:
        maximum=max(maximum,value);values.append(gcd(value,maximum))
    values.sort()
    return sum(gcd(values[i],values[-i-1]) for i in range(len(values)//2))

